mapper.select:
select from automation_workspace_active_versions where application_workspace_id in
#{workspaceId}
order by application_workspace_id

mapper.insert:
insert into automation_workspace_active_versions(
    application_workspace_id, version_id, activated_by_user_id, activated_at, created_at, updated_at
) values (
    #{row.applicationWorkspaceId}, #{row.versionId}, #{row.activatedByUserId},
    #{row.activatedAt}, #{row.createdAt}, #{row.updatedAt}
)
on conflict (application_workspace_id) do nothing

insert into automation_workspace_active_versions(
    application_workspace_id, version_id, activated_by_user_id, activated_at, created_at, updated_at
)
select #{row.applicationWorkspaceId}, #{row.versionId}, #{row.activatedByUserId},
       #{row.activatedAt}, #{row.createdAt}, #{row.updatedAt}
where not exists (
    select 1 from automation_workspace_active_versions
    where application_workspace_id = #{row.applicationWorkspaceId}
)

mapper.update:
update automation_workspace_active_versions
set version_id = #{row.versionId},
    activated_by_user_id = #{row.activatedByUserId},
    activated_at = #{row.activatedAt},
    updated_at = #{row.updatedAt}
where application_workspace_id = #{row.applicationWorkspaceId}
